<?php
namespace App\Models\FbMarketing;
use Illuminate\Database\Eloquent\Model;
class FbmSyncRunItem extends Model{protected $table='fbm_sync_run_items';protected $guarded=[];protected $casts=['safe_summary'=>'array','seen_count'=>'integer','upserted_count'=>'integer','unavailable_count'=>'integer','warning_count'=>'integer'];public function syncRun(){return $this->belongsTo(FbmSyncRun::class,'fbm_sync_run_id');}public function connection(){return $this->belongsTo(FbmConnection::class,'fbm_connection_id');}public function adAccount(){return $this->belongsTo(FbmAdAccount::class,'fbm_ad_account_id');}public function toSafeSummary():array{return ['id'=>(int)$this->id,'family'=>(string)$this->family,'status'=>(string)$this->status,'connection_name'=>optional($this->connection)->connection_name,'ad_account_name'=>optional($this->adAccount)->asset_name,'seen_count'=>(int)$this->seen_count,'upserted_count'=>(int)$this->upserted_count,'unavailable_count'=>(int)$this->unavailable_count,'warning_count'=>(int)$this->warning_count,'redacted_message'=>$this->redacted_message,'safe_summary'=>is_array($this->safe_summary)?$this->safe_summary:[],'created_at'=>optional($this->created_at)->toDateTimeString()];}}
